    throw new Error('RTM Contract Failed - Missing required table: ' + tableName);
  }
  const expectedCount = tableCells(group[0]).length;
  for (const row of group) {
    if (isSeparatorLine(row)) continue;
    const count = tableCells(row).length;
    if (count !== expectedCount) {
      throw new Error('RTM Contract Failed - Table "' + tableName + '" has a row with ' + count + ' columns; expected ' + expectedCount + '. Avoid pipe characters inside cell values.');
    }
  }
}

function validateRtmOutputContract(rawMarkdown, coverageSummary) {
  const text = String(rawMarkdown || '');
  const prompt = $('Prompt Library').item.json || {};
  const context = prompt.traceabilityContext || {};
  const counts = context.counts || {};
  const lower = text.toLowerCase();

  if (/Main Requirement Traceability Matrix Table/i.test(text)) {
    throw new Error('RTM Contract Failed - Legacy "Main Requirement Traceability Matrix Table" section is not allowed.');
  }
  if (/Model:\s*gpt-4o-mini/i.test(text) || /Vector Collection:\s*qa-knowledge-base/i.test(text)) {
    throw new Error('RTM Contract Failed - Hardcoded model/vector metadata found. Use runtime metadata only.');
  }
  if (/\bRisk ID\b/i.test(text) || /\bRSK-[A-Za-z0-9-]+\b/i.test(text)) {
    throw new Error('RTM Contract Failed - Risk IDs are not available in the RTM context and must not be invented.');
  }
  if (/\bfully\s+(?:implemented|tested|validated|verified)|\bimplemented\s+and\s+tested\b|\btests?\s+passed\b|\bproduction[-\s]?ready\b/i.test(text)) {
    throw new Error('RTM Contract Failed - Delivery/execution status claims are not supported by the current RTM evidence.');
  }
  if (/\|\s*Number of Test Cases\s*\|/i.test(text)) {
    throw new Error('RTM Contract Failed - Coverage by Test Category must not use Number of Test Cases unless numeric counts are available. Use Coverage Scope and Evidence Basis.');
  }
  const hasAutomationColumn = markdownTableGroups(text).some(rows => tableCells(rows[0]).some(cell => /^automation status$/i.test(cell)));
  const hasAutomationPercentage = /approx(?:imate|\.)?\s*\d+%\s*automation|\b\d+%\s*automation/i.test(text);
  const hasInventedAutomationCell = markdownTableGroups(text).some(rows => rows.slice(2).some(row => tableCells(row).some(cell => /^(automated|partially automated|manual|not automated)$/i.test(cell))));
  if (hasAutomationColumn || hasAutomationPercentage || hasInventedAutomationCell) {
    throw new Error('RTM Contract Failed - Automation columns, percentages, or invented automation statuses are not available in the RTM context.');
  }
  if (/[A-Z][A-Z0-9]+-\d+\s*\.\.\s*[A-Z][A-Z0-9]+-\d+/.test(text)) {
    throw new Error('RTM Contract Failed - Test case range shorthand is not allowed. List actual test case keys.');
  }

  const coverageLedgerHeadingCount = headingCount(text, 'Coverage Ledger');
  if (coverageLedgerHeadingCount !== 1) {
    throw new Error('RTM Contract Failed - Expected exactly one Coverage Ledger heading, found ' + coverageLedgerHeadingCount + '.');
  }
  const layer2HeadingCount = headingCount(text, 'Layer 2 - User Stories to Generated Test Cases');
  if (layer2HeadingCount !== 1) {
    throw new Error('RTM Contract Failed - Expected exactly one Layer 2 heading, found ' + layer2HeadingCount + '.');
  }

  validateNamedTable(text, 'Layer 1 - Requirements to Epics/User Stories', ['Req ID', 'Requirement Description', 'Source Reference', 'Jira Epic Key', 'Jira Story Key', 'Backlog Coverage Status']);
  validateNamedTable(text, 'Layer 2 - User Stories to Generated Test Cases', ['Story Key', 'Story Summary', 'Test Case Keys', 'Unique Test Case Count', 'Test Categories', 'Test Coverage Status']);
  validateNamedTable(text, 'Coverage by Test Category', ['Test Category', 'Coverage Scope', 'Evidence Basis', 'Notes']);
  validateNamedTable(text, 'Coverage Ledger', ['Coverage ID', 'Module / Requirement', 'Source Reference', 'Included In Output', 'Coverage Status', 'Notes']);

  const expectedStoryKeys = [...new Set((context.stories || []).map(story => story.storyKey).filter(Boolean))];
  const missingStories = expectedStoryKeys.filter(key => !text.includes(key));
  if (missingStories.length) {
    throw new Error('RTM Contract Failed - Missing story key(s) from output: ' + missingStories.slice(0, 10).join(', '));
  }

  const expectedTestCaseKeys = [...new Set((context.storyTestCaseLinks || []).map(link => link.testcaseKey).filter(Boolean))];
  const missingTestCases = expectedTestCaseKeys.filter(key => !text.includes(key));
  if (missingTestCases.length) {
    throw new Error('RTM Contract Failed - Missing generated test case key(s) from output: ' + missingTestCases.slice(0, 15).join(', ') + (missingTestCases.length > 15 ? '...' : ''));
  }

  const ledgerCount = Number(coverageSummary.coverageLedgerCount) || 0;
  const declaredPatterns = [
    /Defines\s+(\d+)\s+key requirements/i,
    /Total Requirements Analyzed:\s*(\d+)/i,
    /Total Requirements Identified:\s*(\d+)/i
  ];
  for (const pattern of declaredPatterns) {
    const match = text.match(pattern);
    if (match && ledgerCount && Number(match[1]) !== ledgerCount) {
      throw new Error('RTM Contract Failed - Requirement count mismatch. Declared ' + match[1] + ' but coverage ledger has ' + ledgerCount + '.');
    }
  }

  if (!lower.includes('layer 1 - requirements to epics/user stories') || !lower.includes('layer 2 - user stories to generated test cases')) {
    throw new Error('RTM Contract Failed - Required Layer 1 and Layer 2 section titles were not found.');
  }

  const misleadingMissingStoryLine = String(text || '').split(/\r?\n/).some(line => {
    const trimmed = line.trim();
    if (/^#{1,6}\s*/.test(trimmed)) return false;
    if (!/stories? without test case/i.test(trimmed)) return false;
    return !/(^|[:\-\s])(?:0|none|no)\b/i.test(trimmed);
  });
  if (Number(counts.storiesWithoutTestCases || 0) === 0 && misleadingMissingStoryLine) {
    throw new Error('RTM Contract Failed - Output suggests missing story test coverage even though context has zero missing stories.');
  }
}

const sharedCoveragePlanningTypes = new Set(['test_strategy', 'test_plan', 'risk_matrix']);
function normalizeCoverageStatus(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (['covered', 'passed', 'complete', 'completed', 'ok'].includes(normalized)) return 'covered';
  if (['partial', 'partially_covered', 'review', 'needs_review', 'warning'].includes(normalized)) return 'partial';
  if (['missing', 'not_covered', 'failed', 'no'].includes(normalized)) return 'missing';
  if (['excluded', 'out_of_scope', 'not_applicable', 'n/a'].includes(normalized)) return 'excluded';
  return normalized || 'unknown';
}

function coverageRowKey(row) {
  return [
    row.coverageId || row.coverageID || row.id || '',
    row.moduleRequirement || row.module || row.requirement || row['Module / Requirement'] || '',
    row.sourceReference || row.source || row['Source Reference'] || ''
  ].map(value => String(value || '').trim().toLowerCase()).filter(Boolean).join('|');
}

function normalizeCoverageRow(row, index) {
  const raw = row && typeof row === 'object' ? row : {};
  return {
    key: coverageRowKey(raw) || 'row-' + index,
    coverageId: raw.coverageId || raw.coverageID || raw.id || raw['Coverage ID'] || 'COV-' + String(index + 1).padStart(3, '0'),
    moduleRequirement: raw.moduleRequirement || raw.module || raw.requirement || raw['Module / Requirement'] || 'Coverage item ' + (index + 1),
    sourceReference: raw.sourceReference || raw.source || raw['Source Reference'] || '',
    includedInOutput: raw.includedInOutput || raw.included || raw['Included In Output'] || '',
    coverageStatus: normalizeCoverageStatus(raw.coverageStatus || raw.status || raw['Coverage Status']),
    notes: raw.notes || raw['Notes'] || ''
  };
}

function buildCoverageBatchSummary(documentType, coverageLedger, coverageSummary) {
  if (documentType !== 'traceability_matrix') return null;
  const rows = (Array.isArray(coverageLedger) ? coverageLedger : []).map(normalizeCoverageRow);
  const batches = rows.map(row => ({
    id: row.coverageId,
    label: row.moduleRequirement,
    sourceReference: row.sourceReference,
    status: row.coverageStatus === 'covered' || row.coverageStatus === 'excluded'
      ? 'complete'
      : row.coverageStatus === 'partial'
        ? 'partial'
        : 'missing',
    coverageStatus: row.coverageStatus,
    notes: row.notes,
    includedInOutput: row.includedInOutput
  }));
  const completedBatches = batches.filter(batch => batch.status === 'complete').length;
  const partialBatches = batches.filter(batch => batch.status === 'partial').length;
  const missingBatches = batches.filter(batch => batch.status === 'missing').length;
  const totalBatches = batches.length || Number(coverageSummary.coverageLedgerCount) || 0;
  return {
    enabled: true,
    version: 'rtm-coverage-batches-v1',
    documentType,
    totalBatches,
    completedBatches,
    partialBatches,
    missingBatches,
    recoveredBatches: 0,
    progressPercent: totalBatches ? Math.round((completedBatches / totalBatches) * 100) : 0,
    batches
  };
}

function buildRtmUpdateSummary(documentType, generationMode, updateContext, coverageLedger, coverageSummary, batchSummary) {
  if (documentType !== 'traceability_matrix') return null;
  const currentRows = (Array.isArray(coverageLedger) ? coverageLedger : []).map(normalizeCoverageRow);
  const previousRows = (Array.isArray(updateContext?.previousCoverageLedger) ? updateContext.previousCoverageLedger : []).map(normalizeCoverageRow);
  const previousByKey = new Map(previousRows.map(row => [row.key, row]));
  const currentByKey = new Map(currentRows.map(row => [row.key, row]));
  let createdCoverageRows = 0;
  let updatedCoverageRows = 0;
  let reusedCoverageRows = 0;

  for (const row of currentRows) {
    const previous = previousByKey.get(row.key);
    if (!previous) {
      createdCoverageRows += 1;
      continue;
    }
    const currentComparable = JSON.stringify({
      status: row.coverageStatus,
      included: row.includedInOutput,
      notes: row.notes
    });
    const previousComparable = JSON.stringify({
      status: previous.coverageStatus,
      included: previous.includedInOutput,
      notes: previous.notes
    });
    if (currentComparable === previousComparable) reusedCoverageRows += 1;
    else updatedCoverageRows += 1;
  }

  const removedCoverageRows = previousRows.filter(row => !currentByKey.has(row.key)).length;
  const missingCoverageRows = Number(coverageSummary.missingCount) || 0;
  const partialCoverageRows = Number(coverageSummary.partialCount) || 0;
  const reviewCoverageRows = missingCoverageRows + partialCoverageRows + (Number(coverageSummary.unknownCount) || 0);
  const noChangesDetected = generationMode === 'update'
    && previousRows.length > 0
    && createdCoverageRows === 0
    && updatedCoverageRows === 0
    && removedCoverageRows === 0;

  return {
    enabled: true,
    version: 'rtm-update-summary-v1',
    documentType,
    mode: generationMode || 'create',
    sourceOfTruth: updateContext?.updateSourceOfTruth || 'current_traceability_context',
    updateOfJobId: updateContext?.previousJobId || null,
    previousConfluencePageId: updateContext?.previousConfluencePageId || null,
    previousCoverageRows: previousRows.length,
    currentCoverageRows: currentRows.length,
    createdCoverageRows,
    updatedCoverageRows,
    reusedCoverageRows,
    removedCoverageRows,
    missingCoverageRows,
    partialCoverageRows,
    reviewCoverageRows,
    noChangesDetected,
    message: generationMode === 'update'
      ? noChangesDetected
        ? 'No traceability changes were detected in the current source context.'
        : 'RTM was refreshed against the current backlog and story test case traceability context.'
      : 'RTM was created from the current backlog and story test case traceability context.',
    batchSummary
  };
}


function evaluateSharedCoveragePlanning(documentType, coverageLedger, coverageSummary) {
  if (!sharedCoveragePlanningTypes.has(documentType)) return null;

  const summary = coverageSummary || {};
  const ledgerCount = coverageLedger.length;
  const partialCount = Number(summary.partialCount) || 0;
  const missingCount = Number(summary.missingCount) || 0;
  const unknownCount = Number(summary.unknownCount) || 0;
  const warningCount = partialCount + missingCount + unknownCount;
  const profile = $('Prompt Library').item.json.coveragePlanningRequirement?.profile || {};

  if (!ledgerCount) {
    summary.gateStatus = 'warning';
    return {
      enabled: true,
      version: 'coverage-planning-v1',
      documentType,
      status: 'warning',
      reason: 'missing_coverage_ledger',
      ledgerCount,
      warningCount: 1,
      message: 'Coverage Ledger was not reported. Review the document for missed source modules or regenerate if audit coverage is required.',
      profileLabel: profile.label || documentType
    };
  }

  const status = warningCount > 0 ? 'warning' : 'passed';
  summary.gateStatus = status === 'warning' ? 'warning' : summary.gateStatus;
  return {
    enabled: true,
    version: 'coverage-planning-v1',
    documentType,
    status,
    reason: status === 'warning' ? 'coverage_gaps_reported' : 'coverage_ledger_clean',
