function tableSafeCell(value) {
  const normalized = String(value ?? 'Not available')
    .replace(/\[[^\]\n]*\|[^\]\n]*\]/g, match => match.slice(1, -1).replace(/\|/g, ' - '))
    .replace(/\|/g, '-')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
